table+' SET parameter_id=parameter_id+90,id=id+90');db.run('UPDATE workflow_category_option SET categorical_id=categorical_id+90,id=id+90');for(const table of['workflow_parameter_binding','workflow_input','workflow_input_binding'])db.run('UPDATE '+table+' SET id=id+90');db.run('UPDATE workflow_output_binding SET id=id+90,path_template=?',['edited\0世界']);await Bun.write(Bun.stdout,db.serialize());db.close();"#;
 let edited=oracle(script,&file(&expected));for value in &mut expected.output_bindings{value.path_template="edited\0世界".into()}assert_eq!(restore(&import_sqlite_database(&edited,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()),expected);
}
